from __future__ import annotations
from typing import List, Tuple

Vertex = Tuple[bool, ...]
PartialCube = List[Vertex]


def is_harmonic_even(V: PartialCube) -> bool:
    """Return True iff every cut splits V into two equal-size opposite semicubes.

    Runs in O(m*n) time (m = #vertices, n = #coordinates) and O(1) extra space
    per coordinate.
    """
    if not V:
        return True
    m = len(V)
    n = len(V[0])
    if m % 2 == 1:
        return False  # an odd number of vertices can never balance any cut
    for i in range(n):
        ones = 0
        for v in V:
            if v[i]:
                ones += 1
        if 2 * ones != m:
            return False
    return True

from __future__ import annotations
from typing import List, Tuple

Vertex = Tuple[bool, ...]
PartialCube = List[Vertex]


def is_harmonic_even(V: PartialCube) -> bool:
    if not V:
        return True
    m = len(V)
    if m % 2 == 1:
        return False
    n = len(V[0])
    return all(2 * sum(1 for v in V if v[i]) == m for i in range(n))


def product_harmonic_even(P: PartialCube, R: PartialCube) -> bool:
    """Decide harmonic-evenness of the box product P box R WITHOUT building it.

    By multiplicativity of balance, for nonempty factors the product is
    harmonic-even iff both factors are. This costs O(m_P*n_P + m_R*n_R) instead of
    the O(m_P*m_R*(n_P+n_R)) needed to materialise and scan the product.
    """
    if not P or not R:
        # empty product is vacuously harmonic-even; nonemptiness is required for
        # the factored criterion to reflect the factors.
        return True
    return is_harmonic_even(P) and is_harmonic_even(R)
